// Strings: a modelled cello (and later a violin), measured from recordings.
//
// A note is the cello's recorded onset (the bow's catch, its scratch and its pitch glide, 0.3 s)
// handing over to a model: a bank of harmonics whose steady spectrum is source x body, kept alive by
// the bow's own movement as measured (pitch, level and each harmonic wandering), with the bow's
// noise in octave bands pulsing at the string's period, and a release that lets each harmonic ring
// down at the rate measured from the staccatos. Everything comes from src/CelloData.h, generated by
// tools/analyze.py and tools/make_header.py; docs/MODEL.md says how.
#include <synthkit/synth.h>

#include <cmath>
#include <cstdint>
#include <cstring>

#include "CelloData.h"

using namespace sk;
namespace cd = cello_data;

namespace {

constexpr int kMaxHarm = cd::kHarm;
constexpr int kGrid = 32;               // the voice's own step (samples of its time): wander, glide, release
constexpr float kGlideS = 0.15f;        // from the onset's harmonics to the steady spectrum
constexpr float kLifeInS = 0.3f;        // the bow's movement comes in over this, from the hand-off's end
constexpr float kOnsetReleaseDbS = 80;  // the onset recording, if a key is let go during it
constexpr float kNoiseReleaseS = 0.015f;
constexpr float kCorrSpan = 3;          // a measured note's own correction fades out over this many semitones
constexpr float kEndDb = -96;
constexpr float kTrimDb = -6;           // headroom: four strings at f peak near 0 dBFS at the recordings' level
constexpr int kFlickBands = 3;          // a harmonic's own movement: three two-octave bands, 0.25-16 Hz
constexpr int kFlickEvery = 4;
// The level moves only slowly: the recordings' level also moves 0.2-0.3 dB per octave at 2-16 Hz,
// but played alone (not tied to the rest of the bow's change) that is a random volume jitter (the
// owner heard it so). A judgment: its octaves from 2 Hz up are left out, and a low-pass at 3 Hz
// closes the slower bands' skirts.
constexpr int kLevelOcts = 3;           // 0.25-2 Hz
constexpr float kLevelLpHz = 3;          // ... updated every 4th step (345 Hz at 44.1 kHz: 17× its 20 Hz top)
constexpr int kGrainTable = 64;
constexpr float kLn10_20 = 0.11512925f; // ln(10) / 20
constexpr float kRecomputeRatio = 1.7345e-3f;  // the spectrum follows the pitch past 3 cents (its detail is 50)

// e^x for gains: 2^f by a 5th-order polynomial (relative error ~2e-7), the exponent in the bits.
// The browser's expf is a software routine, and this runs per harmonic per step.
inline float fastExp(float x) {
  x = dsp::clamp(x, -80.f, 80.f);
  float t = x * 1.44269504f;
  float fi = std::floor(t), f = t - fi;
  float p = 1.f + f * (0.69314718f + f * (0.24022651f + f * (0.05550411f + f * (0.00961813f + f * 0.00133336f))));
  int32_t bits = (static_cast<int32_t>(fi) + 127) << 23;
  float scale;
  std::memcpy(&scale, &bits, sizeof scale);
  return p * scale;
}

// 2^x, the same polynomial as fastExp
inline float fastExp2(float x) { return fastExp(x * 0.69314718f); }

// log2(x) for x > 0: the exponent from the bits, the mantissa by a 4th-order polynomial (~1e-4)
inline float fastLog2(float x) {
  int32_t bits;
  std::memcpy(&bits, &x, sizeof bits);
  float e = static_cast<float>(((bits >> 23) & 255) - 127);
  bits = (bits & 0x007FFFFF) | 0x3F800000;
  float m;
  std::memcpy(&m, &bits, sizeof m);   // 1 ≤ m < 2
  float t = m - 1;
  return e + t * (1.44269504f + t * (-0.72134752f + t * (0.45689917f + t * -0.18326905f)));
}

// log2 of each harmonic number, so a harmonic's log-frequency is one add
struct Log2K {
  float v[cd::kHarm];
  Log2K() { for (int k = 0; k < cd::kHarm; ++k) v[k] = std::log2(float(k + 1)); }
};
const Log2K kLog2K;

// Velocity (0-1) to the dynamic axis: 0 p, 1 mp, 2 mf, 3 f, as the library's sfz maps its layers
// (1-32 p, 33-64 mp, 65-96 mf, 97-127 f: each layer's middle velocity plays it).
float dynOf(float vel) { return dsp::clamp((vel * 127.f - 16.f) / 32.f, 0.f, 3.f); }

float bodyDbLog2(float l2) {
  float x = (l2 - cd::kKnot0) * (1.f / cd::kKnotStep);
  if (x <= 0) return cd::body[0];
  if (x >= cd::kKnots - 1) return cd::body[cd::kKnots - 1];
  int i = static_cast<int>(x);
  float t = x - i;
  return cd::body[i] + t * (cd::body[i + 1] - cd::body[i]);
}

struct InvFitF0 {
  float v[cd::kNotes][cd::kDyns];
  InvFitF0() { for (int n = 0; n < cd::kNotes; ++n) for (int d = 0; d < cd::kDyns; ++d) v[n][d] = 1.f / cd::fitF0[n][d]; }
};
const InvFitF0 kInvFitF0;

// A measured cell's correction at frequency hz (dB), read along its own harmonics.
float corrDb(int note, int dyn, float hz) {
  float x = hz * kInvFitF0.v[note][dyn] - 1;
  if (x < 0 || x >= cd::kHarm - 1) return 0;
  int i = static_cast<int>(x);
  float t = x - i;
  return 0.01f * (cd::corr[note][dyn][i] + t * (cd::corr[note][dyn][i + 1] - cd::corr[note][dyn][i]));
}

// Where a pitch (fractional MIDI) falls among the measured notes: the lower one and the way to the next.
void bracket(double midi, int& lo, float& t) {
  if (midi <= cd::noteMidi[0]) { lo = 0; t = 0; return; }
  if (midi >= cd::noteMidi[cd::kNotes - 1]) { lo = cd::kNotes - 2; t = 1; return; }
  lo = 0;
  while (lo < cd::kNotes - 2 && midi >= cd::noteMidi[lo + 1]) ++lo;
  t = static_cast<float>((midi - cd::noteMidi[lo]) / (cd::noteMidi[lo + 1] - cd::noteMidi[lo]));
}

// A value per (note, dynamic), interpolated in both.
template <typename F>
float cellLerp(int lo, float tn, float dyn, F get) {
  int d0 = std::min(static_cast<int>(dyn), cd::kDyns - 2);
  float td = dyn - d0;
  auto at = [&](int n) { return get(n, d0) + td * (get(n, d0 + 1) - get(n, d0)); };
  return at(lo) + tn * (at(lo + 1) - at(lo));
}

// RBJ band-pass, constant 0 dB peak (the bow noise's, as tools/make_header.py solves against; and the
// wander's octave bands).
struct BandPass {
  float b0 = 0, b2 = 0, a1 = 0, a2 = 0, z1 = 0, z2 = 0;
  void set(float fc, float q, float sr) {
    fc = std::min(fc, 0.45f * sr);
    float w = dsp::kTwoPi * fc / sr, al = std::sin(w) / (2 * q), a0 = 1 + al;
    b0 = al / a0; b2 = -al / a0; a1 = -2 * std::cos(w) / a0; a2 = (1 - al) / a0;
  }
  float process(float x) {
    float y = b0 * x + z1;
    z1 = -a1 * y + z2;
    z2 = b2 * x - a2 * y;
    return y;
  }
  void reset() { z1 = z2 = 0; }
};

// RBJ low-pass (Q 0.707): it closes a harmonic's own movement above 20 Hz, where a band-pass's
// 6 dB/octave skirt would leave sidebands 20-30 dB under each harmonic, over the bow noise between
// them (and over its pulse, which tools/life.py found the recordings have).
struct LowPass {
  float b0 = 0, b1 = 0, b2 = 0, a1 = 0, a2 = 0, z1 = 0, z2 = 0;
  void set(float fc, float sr) {
    fc = std::min(fc, 0.45f * sr);
    float w = dsp::kTwoPi * fc / sr, al = std::sin(w) / (2 * 0.70710678f), c = std::cos(w), a0 = 1 + al;
    b0 = (1 - c) / 2 / a0; b1 = (1 - c) / a0; b2 = b0; a1 = -2 * c / a0; a2 = (1 - al) / a0;
  }
  float process(float x) {
    float y = b0 * x + z1;
    z1 = b1 * x - a1 * y + z2;
    z2 = b2 * x - a2 * y;
    return y;
  }
  void reset() { z1 = z2 = 0; }
};
constexpr float kFlickLpHz = 20;

// The rms a BandPass (then, optionally, a LowPass) gives for unit-variance white noise.
float noiseRms(BandPass f, const LowPass* lp = nullptr) {
  f.reset();
  LowPass l;
  if (lp) l = *lp, l.reset();
  double e = 0;
  float x = 1;
  for (int i = 0; i < 12000; ++i) {   // 13 energy e-folds of the slowest (0.35 Hz) band
    float y = f.process(x);
    if (lp) y = l.process(y);
    x = 0;
    e += double(y) * y;
  }
  return static_cast<float>(std::sqrt(e));
}

// A BandPass driven by unit white noise, in its steady state: the covariance of its two state
// variables (sum over its impulse response of s s^T), as a 2x2 Cholesky factor. Starting a filter
// from a draw of it means the slow wander (1-2 s to build up from rest) moves fully from the start.
struct Stationary {
  float l11 = 0, l21 = 0, l22 = 0;
  void of(const BandPass& f) {
    // DF2T: s' = A s + B x, A = [[-a1, 1], [-a2, 0]], B = [-a1 b0, b2 - a2 b0]
    const double a1 = f.a1, a2 = f.a2, b0 = f.b0, b2 = f.b2;  // widen before multiplying
    double s1 = -a1 * b0, s2 = b2 - a2 * b0, p11 = 0, p12 = 0, p22 = 0;
    for (int i = 0; i < 12000; ++i) {
      p11 += s1 * s1; p12 += s1 * s2; p22 += s2 * s2;
      double n1 = -a1 * s1 + s2, n2 = -a2 * s1;
      s1 = n1; s2 = n2;
    }
    l11 = static_cast<float>(std::sqrt(p11));
    l21 = l11 > 0 ? static_cast<float>(p12 / l11) : 0.f;
    l22 = static_cast<float>(std::sqrt(std::max(0.0, p22 - double(l21) * l21)));
  }
  void draw(BandPass& f, dsp::Rng& r) const {
    float u = r.normal(), v = r.normal();
    f.z1 = l11 * u;
    f.z2 = l21 * u + l22 * v;
  }
};

}  // namespace

struct Strings;

struct StringsVoice : Voice {
  explicit StringsVoice(Strings& s) : synth(s) {}
  void prepare(const PrepareInfo& info) override;
  void start(const NoteOn& n, const StartInfo& s) override;
  void release() override { releasing = true; }
  void render(VoiceContext& ctx, Buffer& out) override;
  bool active() const override { return alive; }

  void setup(VoiceContext& ctx);
  void setRotation(float hz);
  void spectrum(float hz);            // the steady spectrum's targets at this pitch
  void grainShape(float amount);      // the noise pulse's tables
  void step(VoiceContext& ctx);       // one kGrid step of the voice's own time
  void tuneWander(float speed);
  float wanderOctaves(BandPass* f, const float* rms, float scale);

  Strings& synth;
  float sr = 48000;
  bool pending = false, alive = false, releasing = false, released = false;
  float vel = 0, dyn = 0;
  long t = 0;                         // samples since the note started

  // where the note sits among the measured ones
  int lo = 0, d0 = 0;
  float tn = 0, td = 0, wLo = 0, wHi = 0, level = 0, hz0 = 0;

  // the onset: which recording, where in it, how fast it is read
  const short* onset = nullptr;
  double pos = 0, step_ = 1;
  float onsetGain = 0, onsetRel = 1, onsetRelMul = 1;
  long tX0 = 0, tX1 = 0, tC = 0;      // the crossfade and the hand-off instant, in samples

  // the model
  int K = 0;
  bool bankOn = false;
  float zr[kMaxHarm], zi[kMaxHarm], rc[kMaxHarm], rs[kMaxHarm];
  float amp[kMaxHarm], target[kMaxHarm], gain[kMaxHarm], relRate[kMaxHarm];

  float srcDb[kMaxHarm];              // source part of the steady spectrum (per note, fixed)
  float hand[kMaxHarm], handPh[kMaxHarm];
  float specHz = 0, specBody = -1;    // the pitch and Body the targets were computed for
  float glideRate = 0;

  // the bow's movement (cents, dB), as band-limited noise per octave, on the kGrid step
  BandPass wPitch[cd::kOct], wLevel[cd::kOct], wHarm[kMaxHarm][kFlickBands];
  LowPass wHarmLp[kMaxHarm];
  LowPass wLevelLp;
  float rmsPitch[cd::kOct], rmsLevel[cd::kOct], rmsHarm[kFlickBands];
  // the harmonics' shared patterns (the recording's own): a shape over the harmonics and its score,
  // band-limited noise with the measured spectrum; and each harmonic's leftover, independent part
  BandPass wPat[cd::kPat][cd::kOct];
  LowPass wPatLp[cd::kPat];
  float rmsPat[cd::kPat][cd::kOct], score[cd::kPat];
  const float* shape[cd::kPat];
  const float* residK = nullptr;
  float normOct[cd::kOct], normFlick[kFlickBands];   // each filter's rms for unit noise
  Stationary statOct[cd::kOct], statFlick[kFlickBands];   // their steady states (at Speed 100 %)
  float flick[kMaxHarm];
  float wSpeed = -1;
  float pitchC = 0, levelDb = 0;
  dsp::Rng wrng;

  // bow noise, pulsing at the string's period
  BandPass bp[cd::kBands][2];
  float noiseGain[cd::kBands];
  float grain[cd::kBands][kGrainTable + 1];
  float grainDepth[cd::kBands], grainPh[cd::kBands], grainAmount = -1;
  float noiseDrive = 0, noiseRelMul = 1;
  dsp::Rng rng_;

  // parameter values for this render call
  float pLife = 1, pPitch = 1, pFlicker = 1, pSpeed = 1, pBody = 1, pNoiseDb = 0, pGrain = 1, pRelease = 1;
};

struct Strings : Synth {
  Param life, lifePitch, lifeFlicker, lifeSpeed, body, noise, grain, release;

  void defineParams(ParamBuilder& b) override {
    life = b.add("life.amount").name("Life").range(0, 300).def(100).unit("%").modulatable();
    lifePitch = b.add("life.pitch").name("Pitch Wander").range(0, 400).def(100).unit("%").modulatable();
    lifeFlicker = b.add("life.flicker").name("Flicker").range(0, 400).def(100).unit("%").modulatable();
    lifeSpeed = b.add("life.speed").name("Speed").range(25, 400).log().def(100).unit("%").modulatable();
    body = b.add("tone.body").name("Body").range(0, 200).def(100).unit("%").modulatable();
    noise = b.add("tone.noise").name("Bow Noise").range(-30, 24).def(0).unit("dB").modulatable();
    grain = b.add("tone.grain").name("Grain").range(0, 300).def(100).unit("%").modulatable();
    release = b.add("play.release").name("Release").range(25, 400).log().def(100).unit("%").modulatable();
  }
  std::unique_ptr<Voice> makeVoice() override { return std::make_unique<StringsVoice>(*this); }
};

void StringsVoice::prepare(const PrepareInfo& info) {
  sr = static_cast<float>(info.sampleRate);
  for (int b = 0; b < cd::kBands; ++b)
    for (auto& f : bp[b]) f.set(cd::bandHz[b], cd::kNoiseQ, sr);
  // the wander filters' rms for unit noise at the reference speed (they're retuned with Speed; a
  // band-pass of fixed Q passes power in proportion to its centre, so the rms scales by its root)
  const float gr = sr / kGrid;
  for (int o = 0; o < cd::kOct; ++o) {
    BandPass f;
    f.set(cd::kLifeOct0 * std::pow(2.f, o + 0.5f), std::sqrt(2.f), gr);
    normOct[o] = noiseRms(f);
    statOct[o].of(f);
  }
  const float grf = gr / kFlickEvery;
  LowPass lp;
  lp.set(kFlickLpHz, grf);
  for (int j = 0; j < kFlickBands; ++j) {
    BandPass f;
    f.set(cd::kLifeOct0 * std::pow(4.f, j + 0.5f), 0.67f, grf);
    normFlick[j] = noiseRms(f, &lp);   // through the band and the low-pass, as played
    statFlick[j].of(f);
  }
}

void StringsVoice::tuneWander(float speed) {
  const float gr = sr / kGrid;
  for (int o = 0; o < cd::kOct; ++o) {
    float fc = cd::kLifeOct0 * std::pow(2.f, o + 0.5f) * speed;
    wPitch[o].set(fc, std::sqrt(2.f), gr);
    wLevel[o].set(fc, std::sqrt(2.f), gr);
    for (int c = 0; c < cd::kPat; ++c) wPat[c][o].set(fc, std::sqrt(2.f), gr);
  }
  wLevelLp.set(kLevelLpHz * speed, gr);
  for (int c = 0; c < cd::kPat; ++c) wPatLp[c].set(kFlickLpHz * speed, gr);
  const float grf = gr / kFlickEvery;
  for (int k = 0; k < K; ++k) {
    for (int j = 0; j < kFlickBands; ++j) wHarm[k][j].set(cd::kLifeOct0 * std::pow(4.f, j + 0.5f) * speed, 0.67f, grf);
    wHarmLp[k].set(kFlickLpHz * speed, grf);
  }
  wSpeed = speed;
}

void StringsVoice::start(const NoteOn& n, const StartInfo&) {
  vel = n.vel;
  dyn = dynOf(n.vel);
  auto& r = rng();
  rng_.seed(static_cast<uint64_t>(r.integer(1, 1 << 30)));
  wrng.seed(static_cast<uint64_t>(r.integer(1, 1 << 30)));
  pending = true;
  alive = true;
  releasing = released = false;
  bankOn = false;
  t = 0;
}

void StringsVoice::setRotation(float hz) {
  float w = dsp::kTwoPi * hz / sr;
  float c1 = std::cos(w), s1 = std::sin(w), c = 1, s = 0;
  for (int k = 0; k < K; ++k) {
    float nc = c * c1 - s * s1, ns = c * s1 + s * c1;
    c = nc; s = ns;
    rc[k] = c; rs[k] = s;
  }
}

// The steady spectrum at a pitch: the source (fixed for the note) plus the parts that belong to
// frequency, the body and the measured notes' corrections, scaled by Body; normalised to the level.
void StringsVoice::spectrum(float hz) {
  float sum = 0;
  const float l2 = std::log2(hz);
  for (int k = 0; k < K; ++k) {
    float f = (k + 1) * hz;
    float fd = bodyDbLog2(l2 + kLog2K.v[k]);
    if (wLo > 0) fd += wLo * (corrDb(lo, d0, f) + td * (corrDb(lo, d0 + 1, f) - corrDb(lo, d0, f)));
    if (wHi > 0) fd += wHi * (corrDb(lo + 1, d0, f) + td * (corrDb(lo + 1, d0 + 1, f) - corrDb(lo + 1, d0, f)));
    target[k] = fastExp(kLn10_20 * (srcDb[k] + pBody * fd));
    sum += target[k] * target[k];
  }
  float norm = std::sqrt(2.f) * dsp::dbToGain(level) / std::sqrt(sum);
  for (int k = 0; k < K; ++k) target[k] *= norm;
  specHz = hz;
  specBody = pBody;
}

// The noise pulse per band: u^p, u = (1 + cos(θ - ψ)) / 2, with p for the measured depth times
// Grain, normalised to unit mean power so the band's level stays as measured.
void StringsVoice::grainShape(float amount) {
  for (int b = 0; b < cd::kBands; ++b) {
    float d = dsp::clamp(grainDepth[b] * amount, 0.f, 1.9f) / 0.05f;
    int i = std::min(static_cast<int>(d), cd::kGrainSteps - 2);
    float p = cd::grainExp[i] + (d - i) * (cd::grainExp[i + 1] - cd::grainExp[i]);
    double pw = 0;
    for (int j = 0; j < kGrainTable; ++j) {
      float th = dsp::kTwoPi * j / kGrainTable;
      float u = 0.5f + 0.5f * std::cos(th - grainPh[b]);
      grain[b][j] = p > 0 ? std::pow(std::max(u, 1e-9f), p) : 1.f;
      pw += double(grain[b][j]) * grain[b][j];
    }
    float norm = static_cast<float>(1.0 / std::sqrt(pw / kGrainTable));
    for (int j = 0; j < kGrainTable; ++j) grain[b][j] *= norm;
    grain[b][kGrainTable] = grain[b][0];
  }
  grainAmount = amount;
}

// Everything that depends on the note's pitch, read at its first render (parameters and the
// pitch are available there: API.md §4).
void StringsVoice::setup(VoiceContext& ctx) {
  double midi = ctx.pitch();
  float hz = static_cast<float>(ctx.pitchHz());
  hz0 = hz;
  bracket(midi, lo, tn);
  d0 = std::min(static_cast<int>(dyn), cd::kDyns - 2);
  td = dyn - d0;
  level = cellLerp(lo, tn, dyn, [](int a, int b) { return cd::level[a][b]; });

  // the onset: the nearest measured note's, at the nearest dynamic, transposed to this pitch
  int on = tn < 0.5f ? lo : lo + 1;
  if (midi <= cd::noteMidi[0]) on = 0;
  if (midi >= cd::noteMidi[cd::kNotes - 1]) on = cd::kNotes - 1;
  int od = std::min(cd::kDyns - 1, static_cast<int>(dyn + 0.5f));
  onset = cd::onset[on * cd::kDyns + od];
  float ratio = hz / cd::handF0[on][od];
  step_ = ratio * cd::kOnsetRate / sr;
  pos = 0;
  float cellDb = level - cd::level[on][od];
  onsetGain = dsp::dbToGain(cellDb) * cd::kOnsetScale;
  onsetRel = 1;
  onsetRelMul = dsp::dbToGain(-kOnsetReleaseDbS / sr);
  tX0 = static_cast<long>(cd::kTOn * cd::kOnsetRate / step_);
  tX1 = static_cast<long>((cd::kTOn + cd::kXf) * cd::kOnsetRate / step_);
  tC = static_cast<long>(cd::kTC * cd::kOnsetRate / step_);

  // the steady spectrum: source x body, plus the measured notes' own corrections nearby
  K = std::max(1, std::min(kMaxHarm, static_cast<int>(cd::kFMax / hz)));
  wLo = std::max(0.f, 1.f - static_cast<float>(midi - cd::noteMidi[lo]) / kCorrSpan);
  wHi = std::max(0.f, 1.f - static_cast<float>(cd::noteMidi[lo + 1] - midi) / kCorrSpan);
  for (int k = 0; k < K; ++k) srcDb[k] = cd::source[d0][k] + td * (cd::source[d0 + 1][k] - cd::source[d0][k]);
  pBody = ctx.get(synth.body) * 0.01f;
  spectrum(hz);

  // the onset's harmonics at the hand-off, which the bank starts from
  float hg = dsp::dbToGain(cellDb);
  for (int k = 0; k < K; ++k) {
    hand[k] = k < cd::handCount[on][od] ? hg * dsp::dbToGain(0.01f * cd::handDb[on][od][k]) : 0.f;
    handPh[k] = cd::handPh[on][od][k] * (dsp::kPi / 128.f);
    gain[k] = 1;
    flick[k] = 1;
  }

  // the release: each harmonic's band's decay after the bow stops
  for (int k = 0; k < K; ++k) {
    float f = (k + 1) * hz;
    int b = static_cast<int>(std::lround(std::log2(f / cd::bandHz[0])));
    b = std::max(0, std::min(cd::kBands - 1, b));
    float r = cd::releaseDbS[lo][b] + tn * (cd::releaseDbS[lo + 1][b] - cd::releaseDbS[lo][b]);
    relRate[k] = -r / sr * kLn10_20;   // dB/s → ln gain per sample
  }

  // the bow's movement: this note's spectra, the filters' state from rest
  for (int o = 0; o < cd::kOct; ++o) {
    rmsPitch[o] = cd::lifePitch[lo][o] + tn * (cd::lifePitch[lo + 1][o] - cd::lifePitch[lo][o]);
    rmsLevel[o] = o < kLevelOcts ? cd::lifeLevel[lo][o] + tn * (cd::lifeLevel[lo + 1][o] - cd::lifeLevel[lo][o]) : 0.f;
  }
  // the harmonics' own movement: the onset's cell's patterns (the same recording), and its leftover
  // part's spectrum split into the three two-octave bands (up to 16 Hz: the rest is closed off)
  const int cell = on * cd::kDyns + od;
  for (int c = 0; c < cd::kPat; ++c) {
    shape[c] = cd::lifeShape[cell][c];
    // up to 16 Hz only, as a harmonic's leftover movement: faster, its sidebands land between the
    // harmonics as noise (on C3 they put 14-25 dB more there than the recording has)
    for (int o = 0; o < cd::kOct; ++o) rmsPat[c][o] = o < 6 ? cd::lifeShapeOct[cell][c][o] : 0.f;
    wPatLp[c].reset();
    score[c] = 0;
  }
  residK = cd::lifeResidK[cell];
  for (int j = 0; j < kFlickBands; ++j) {
    float a = 0;
    for (int o = 2 * j; o < 2 * j + 2; ++o) a += cd::lifeResidOct[cell][o] * cd::lifeResidOct[cell][o];
    rmsHarm[j] = std::sqrt(a);
  }
  // the wander starts in its steady state (drawn at Speed 100 %'s statistics: near enough at others)
  tuneWander(pSpeed);
  wLevelLp.reset();
  for (int o = 0; o < cd::kOct; ++o) {
    statOct[o].draw(wPitch[o], wrng);
    statOct[o].draw(wLevel[o], wrng);
    for (int c = 0; c < cd::kPat; ++c) statOct[o].draw(wPat[c][o], wrng);
  }
  for (int k = 0; k < K; ++k) {
    for (int j = 0; j < kFlickBands; ++j) statFlick[j].draw(wHarm[k][j], wrng);
    wHarmLp[k].reset();
  }
  pitchC = levelDb = 0;

  // bow noise, as measured, for unit-variance noise at the data's rate
  for (int b = 0; b < cd::kBands; ++b) {
    float g = cellLerp(lo, tn, dyn, [b](int a, int c) { return cd::noiseDb[a][c][b]; });
    // noiseDb: the band's power re the harmonic rms (level), in dB; for noise at sr rather than the
    // data's rate the same filter passes kOnsetRate / sr as much power
    noiseGain[b] = dsp::dbToGain(g + level) * std::sqrt(sr / cd::kOnsetRate);
    grainDepth[b] = cellLerp(lo, tn, dyn, [b](int a, int c) { return cd::grainDepth[a][c][b]; });
    grainPh[b] = cd::grainPhase[on][od][b];
    for (auto& f : bp[b]) f.reset();
  }
  grainAmount = -1;
  noiseDrive = 0;
  noiseRelMul = std::exp(-1.f / (kNoiseReleaseS * sr));
  glideRate = 1.f / (kGlideS * sr);
  setRotation(hz);
}

// Sum of octave-band noises (one white draw each), each scaled to its measured rms.
float StringsVoice::wanderOctaves(BandPass* f, const float* rms, float scale) {
  float y = 0;
  for (int o = 0; o < cd::kOct; ++o) {
    if (rms[o] < 1e-4f) continue;
    y += f[o].process(wrng.bipolar() * 1.7320508f) * rms[o] / normOct[o];
  }
  return y * scale;
}

// One kGrid step of the voice's own time: the bow's movement, the spectrum following the pitch,
// the glide and the release. Done on the voice's clock, never per render call, so the result
// doesn't depend on the block size.
void StringsVoice::step(VoiceContext& ctx) {
  float hz = static_cast<float>(ctx.pitchHz());

  // the life comes in once the hand-off is over (during it the model must match the recording);
  // it stops moving when the bow leaves
  float lifeW = dsp::clamp((t - tX1) / (kLifeInS * sr), 0.f, 1.f) * pLife;
  if (!released && bankOn) {
    if (pSpeed != wSpeed) tuneWander(pSpeed);
    const float sp = 1.f / std::sqrt(pSpeed);   // a filter's rms for unit noise grows with its centre
    pitchC = wanderOctaves(wPitch, rmsPitch, sp * lifeW * pPitch);
    levelDb = dsp::clamp(wLevelLp.process(wanderOctaves(wLevel, rmsLevel, sp * lifeW)), -12.f, 12.f);
    // each harmonic's own movement is measured against the note's level, so it moves energy between
    // the harmonics and leaves the level to the level's own wander: c takes out what it would add
    float fl = sp * lifeW * pFlicker;
    for (int c = 0; c < cd::kPat; ++c) score[c] = wPatLp[c].process(wanderOctaves(wPat[c], rmsPat[c], 1.f));
    const bool flickNow = (t / kGrid) % kFlickEvery == 0;
    float num = 0, den = 0;
    for (int k = 0; k < K; ++k) {
      if (!flickNow) {   // between updates each harmonic keeps its own movement; the sums still follow amp
        float a2 = amp[k] * amp[k];
        num += a2 * flick[k] * flick[k];
        den += a2;
        continue;
      }
      float h = 0;
      // unit-variance uniform draws: the narrow filters make their output Gaussian enough, and a
      // normal draw costs a log, a cos and a square root
      for (int j = 0; j < kFlickBands; ++j) h += wHarm[k][j].process(wrng.bipolar() * 1.7320508f) * rmsHarm[j] / normFlick[j];
      h = wHarmLp[k].process(h) * residK[k];
      if (k < cd::kPatHarm)
        for (int c = 0; c < cd::kPat; ++c) h += shape[c][k] * score[c];
      // a harmonic can sink far but rise only so much: Life and Flicker multiply, and at their tops a
      // high harmonic's own movement would otherwise swing by tens of dB
      flick[k] = fastExp(kLn10_20 * dsp::clamp(fl * h, -40.f, 12.f));   // as a gain
      float a2 = amp[k] * amp[k];
      num += a2 * flick[k] * flick[k];
      den += a2;
    }
    const float lg = fastExp(kLn10_20 * levelDb) * (num > 0 ? std::sqrt(den / num) : 1.f);
    for (int k = 0; k < K; ++k) gain[k] = lg * flick[k];
  }

  float f = hz * std::exp2(pitchC / 1200.f);
  setRotation(f);
  // the body and corrections follow the pitch (past 3 cents: their detail is 50) and Body
  if (!released && (std::fabs(f / specHz - 1.f) > kRecomputeRatio || pBody != specBody)) spectrum(f);

  if (bankOn) {
    if (released) {
      float rel = 1.f / pRelease;
      for (int k = 0; k < K; ++k) amp[k] *= fastExp(relRate[k] * rel * kGrid);
    } else if (t >= tX1) {
      float g = 1.f - std::exp(-glideRate * kGrid);
      for (int k = 0; k < K; ++k) amp[k] += g * (target[k] - amp[k]);
    }
  }
  if (!released && std::fabs(pGrain - grainAmount) > 0.01f) grainShape(pGrain);
  // Each rotator carries its harmonic's amplitude. Aim it at this step's amp × gain by a growth
  // per sample folded into its rotation: a smooth (exponential) ramp across the step, at no cost
  // per sample, since a staircase would spread every harmonic into sidebands at the step's rate.
  // Re-aimed every step from where it is, so rounding never drifts.
  if (bankOn) {
    for (int k = 0; k < K; ++k) {
      float m2 = zr[k] * zr[k] + zi[k] * zi[k];
      float d = std::max(amp[k] * gain[k], 1e-12f);
      float lr = dsp::clamp(fastLog2(d * d / std::max(m2, 1e-30f)) * (0.5f / kGrid), -1.f, 1.f);
      float rho = fastExp2(lr);
      rc[k] *= rho;
      rs[k] *= rho;
    }
  }
}

void StringsVoice::render(VoiceContext& ctx, Buffer& out) {
  pLife = ctx.get(synth.life) * 0.01f;
  pPitch = ctx.get(synth.lifePitch) * 0.01f;
  pFlicker = ctx.get(synth.lifeFlicker) * 0.01f;
  pSpeed = ctx.get(synth.lifeSpeed) * 0.01f;
  pBody = ctx.get(synth.body) * 0.01f;
  pNoiseDb = ctx.get(synth.noise);
  pGrain = ctx.get(synth.grain) * 0.01f;
  pRelease = ctx.get(synth.release) * 0.01f;
  if (pending) {
    setup(ctx);
    pending = false;
  }
  if (releasing && !released) released = true;
  const int n = out.frames;
  const float trim = dsp::dbToGain(kTrimDb);
  const float noiseLevel = dsp::dbToGain(pNoiseDb);
  float energy = 0;

  int i = 0;
  while (i < n) {
    if (t % kGrid == 0) {
      // start the bank at the crossfade, its phases set so that each harmonic meets the recording's
      // at tC. A note let go before it still hands over: the string rings on after the bow leaves,
      // from the level the onset has decayed to.
      if (!bankOn && t + kGrid > tX0) {
        float hz = static_cast<float>(ctx.pitchHz());
        for (int k = 0; k < K; ++k) {
          double ph = handPh[k] - static_cast<double>(k + 1) * dsp::kTwoPi * hz / sr * static_cast<double>(tC - t);
          amp[k] = hand[k] * (released ? onsetRel : 1.f);
          float a = std::max(amp[k], 1e-12f);
          zr[k] = static_cast<float>(a * std::cos(ph));
          zi[k] = static_cast<float>(a * std::sin(ph));
        }
        bankOn = true;
      }
      step(ctx);
    }
    const int seg = std::min(n - i, kGrid - static_cast<int>(t % kGrid));
    const float lvl = std::exp(kLn10_20 * levelDb) * noiseLevel;
    for (int s = 0; s < seg; ++s, ++i) {
      long ti = t + s;
      // crossfade weight of the model (raised cosine over [tX0, tX1])
      float mw = ti <= tX0 ? 0.f : ti >= tX1 ? 1.f : 0.5f - 0.5f * std::cos(dsp::kPi * (ti - tX0) / float(tX1 - tX0));
      float y = 0;
      // the onset recording
      if (onset && mw < 1) {
        int ip = static_cast<int>(pos);
        if (ip + 2 < cd::kOnsetLen) {
          float fr = static_cast<float>(pos - ip);
          float xm = ip > 0 ? onset[ip - 1] : 0.f, x0 = onset[ip], x1 = onset[ip + 1], x2 = onset[ip + 2];
          float c1 = 0.5f * (x1 - xm), c2 = xm - 2.5f * x0 + 2 * x1 - 0.5f * x2, c3 = 0.5f * (x2 - xm) + 1.5f * (x0 - x1);
          y += (1 - mw) * onsetGain * onsetRel * (((c3 * fr + c2) * fr + c1) * fr + x0);
        }
        pos += step_;
        if (released) onsetRel *= onsetRelMul;
      }
      // the harmonics, and where the fundamental is in its period (for the noise's pulse)
      float th = 0;
      if (bankOn) {
        float h = 0;
        for (int k = 0; k < K; ++k) {
          h += zr[k];
          float r = zr[k] * rc[k] - zi[k] * rs[k];
          zi[k] = zr[k] * rs[k] + zi[k] * rc[k];
          zr[k] = r;
        }
        y += mw * h;
      }
      // bow noise: follows the model in, pulses with the string, stops quickly when the bow leaves
      if (!released) noiseDrive = mw;
      else noiseDrive *= noiseRelMul;
      if (noiseDrive > 1e-5f) {
        if (bankOn) th = std::atan2(zi[0], zr[0]);   // the rotator's angle: its amplitude doesn't matter
        float x = (th < 0 ? th + dsp::kTwoPi : th) * (kGrainTable / dsp::kTwoPi);
        int j = std::min(static_cast<int>(x), kGrainTable - 1);
        float fj = x - j;
        // each band its own noise: driven by one, neighbouring bands' outputs would be correlated
        // and partly cancel where they overlap (6-13 dB short in places), where tools/make_header.py
        // solves the gains for powers that add
        float nz = 0;
        for (int b = 0; b < cd::kBands; ++b) {
          float e = grain[b][j] + fj * (grain[b][j + 1] - grain[b][j]);
          nz += noiseGain[b] * e * bp[b][1].process(bp[b][0].process(rng_.bipolar() * 1.7320508f));
        }
        y += noiseDrive * lvl * nz;
      }
      y *= trim;
      out.add(i, y);
      energy += y * y;
    }
    t += seg;
  }

  if (released) {
    float sum = 0;
    for (int k = 0; k < K && bankOn; ++k) sum += amp[k] * amp[k];
    float onsetLeft = (onset && t < tX1) ? onsetRel * dsp::dbToGain(-20.f) : 0.f;
    float lv = 0.5f * sum + onsetLeft * onsetLeft + noiseDrive * noiseDrive * 1e-3f;
    if (lv < dsp::dbToGain(2 * kEndDb) && energy / n < dsp::dbToGain(2 * kEndDb)) alive = false;
  }
}

